"""Writes ews_golden.json: ewstools 2.1.3's own outputs on fixed inputs, the reference that
tipping_point.ews.indicators and trend are held to. Run once, outside the gate, from the repo root:

  uv run --isolated --no-project --with ewstools==2.1.3 python \
      python/tipping_point/tests/fixtures/make_ews_golden.py

ewstools is never a dependency of the package or the gate; only this script imports it. The
inputs are stored in the fixture, so later numpy versions cannot change what is compared.
"""

import json
import sys
from importlib.metadata import version
from pathlib import Path

import ewstools  # pyright: ignore[reportMissingImports]
import numpy as np

OUT = Path(__file__).with_name("ews_golden.json")


def _ar1(rng: np.random.Generator, phi: float, scale: np.ndarray) -> np.ndarray:
    x = np.zeros(len(scale))
    for t in range(1, len(scale)):
        x[t] = phi * x[t - 1] + scale[t] * rng.standard_normal()
    return x


def _floats(values: np.ndarray) -> list[float | None]:
    return [None if np.isnan(v) else float(v) for v in values]


def _case(x: np.ndarray, window: int, lag: int, bandwidth: float | None) -> dict:
    ts = ewstools.TimeSeries(data=x)
    if bandwidth is not None:
        ts.detrend(method="Gaussian", bandwidth=bandwidth)
    ts.compute_var(rolling_window=window)
    ts.compute_auto(rolling_window=window, lag=lag)
    ts.compute_skew(rolling_window=window)
    ts.compute_ktau()
    case = {
        "window": window,
        "lag": lag,
        "bandwidth": bandwidth,
        "x": _floats(x),
        "variance": _floats(ts.ews["variance"].to_numpy()),
        "autocorrelation": _floats(ts.ews[f"ac{lag}"].to_numpy()),
        "skewness": _floats(ts.ews["skew"].to_numpy()),
        "ktau": {
            "variance": float(ts.ktau["variance"]),
            "autocorrelation": float(ts.ktau[f"ac{lag}"]),
            "skewness": float(ts.ktau["skew"]),
        },
    }
    if bandwidth is not None:
        case["smoothing"] = _floats(ts.state["smoothing"].to_numpy())
        case["residuals"] = _floats(ts.state["residuals"].to_numpy())
    return case


def main() -> None:
    rng = np.random.default_rng(26)
    n = 600
    t = np.arange(n)
    # AR(1) whose memory is fixed, on a trend that Gaussian detrending must remove
    trended = _ar1(rng, 0.8, np.full(n, 1.0)) + 0.01 * t + 2.0 * np.sin(t / 60.0) + 5.0
    # AR(1) whose noise grows, so variance has a trend to score; no detrending, lag 3
    growing = _ar1(rng, 0.6, np.linspace(0.5, 2.0, n))
    # a kernel far wider than the series: scipy keeps reflecting past both ends
    short = _ar1(rng, 0.5, np.full(120, 1.0)) + np.linspace(0.0, 3.0, 120)
    record = {
        "source": "ewstools.TimeSeries: detrend('Gaussian'), compute_var, compute_auto, "
        "compute_skew, compute_ktau; generated by make_ews_golden.py",
        "versions": {name: version(name) for name in ("ewstools", "pandas", "scipy", "numpy")}
        | {"python": sys.version.split()[0]},
        "cases": {
            "trended_detrended": _case(trended, window=150, lag=1, bandwidth=120.0),
            "growing_raw_lag3": _case(growing, window=200, lag=3, bandwidth=None),
            "short_wide_kernel": _case(short, window=40, lag=1, bandwidth=400.0),
        },
    }
    OUT.write_text(json.dumps(record, indent=1) + "\n", encoding="utf-8")
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
